class_name DialogPlayer

@export var tree: DialogTree

signal line_shown(speaker: String, text: String, choices_labels: Array)
signal dialog_finished

var _current_node: DialogNode
var _flags: Dictionary = {}


func start():
	if tree == null:
		push_error("DialogPlayer: No DialogTree assigned")
		return
	_current_node = tree.get_node(tree.start_id)
	_emit_line()


func set_flag(name: StringName):
	_flags[name] = true


func has_flag(name: StringName) -> bool:
	return _flags.has(name)


func advance(choice_index: int = -1):
	if _current_node == null:
		return

	var next_id: StringName
	var visible := _current_node.get_visible_choices(_flags)

	if not visible.is_empty():
		if choice_index >= 0 and choice_index < _current_node.choices.size():
			var choice = _current_node.choices[choice_index]
			# Only follow the choice if it's currently visible.
			if choice.is_visible(_flags):
				next_id = choice.next_id
			else:
				push_warning("DialogPlayer: choice at index %d is not visible" % choice_index)
				return
		else:
			push_warning("DialogPlayer: invalid choice_index %d" % choice_index)
			return
	else:
		next_id = _current_node.next_id

	if next_id.is_empty():
		dialog_finished.emit()
		_current_node = null
		return

	_current_node = tree.get_node(next_id)
	if _current_node == null:
		push_error("DialogPlayer: node not found for id: %s" % next_id)
		dialog_finished.emit()
		return

	_emit_line()


func _emit_line():
	var labels = _current_node.get_visible_choices(_flags)
	line_shown.emit(_current_node.speaker, _current_node.text, labels)
